window.ISMBusinessPodcasts=[{"id":"idioms-to-clear-actions","title":"Reuniões: expressões que viram ações claras","lesson":"business-practice.html#idioms-to-clear-actions/0","image":"assets/reference-meeting-language.svg","versions":{"pt":{"label":"Português + exemplos em inglês","chapters":[{"id":"opening","title":"Comece pelo contexto","segments":[{"lang":"pt-BR","text":"Bem-vindo a uma aula em áudio do ISM Business. Este episódio usa situações profissionais fictícias. Na primeira vez, acompanhe o sentido. Depois retorne aos capítulos e pratique em voz alta. Pause sempre que precisar de mais tempo. A narração é sintetizada. Os personagens usam vozes neurais diferentes em inglês.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":0.0,"end":18.651},{"lang":"pt-BR","text":"Conheça a situação que vamos praticar.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":19.151,"end":21.719},{"lang":"en-US","text":"A new colleague joins your project team. Explain useful meeting expressions, check understanding and agree on a clear written action.","pauseMs":1300,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":22.219,"end":30.837},{"lang":"pt-BR","text":"Ao final, explique uma expressão útil, participe da conversa e deixe claro um próximo passo. Você não precisa decorar todas as frases. O objetivo é comunicar a mensagem com suas próprias palavras.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":32.137,"end":44.227}],"start":0.0,"end":44.727},{"id":"vocabulary","title":"Vocabulário explicado","segments":[{"lang":"pt-BR","text":"Vamos trabalhar doze expressões úteis. Para cada uma, ouça o termo, compreenda o sentido e acompanhe uma frase de exemplo. Use a pausa depois do exemplo para repetir ou criar uma frase semelhante.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":44.727,"end":56.244},{"lang":"en-US","text":"get the ball rolling.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":56.744,"end":58.253},{"lang":"pt-BR","text":"dar início.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":58.553,"end":59.703},{"lang":"en-US","text":"We can get the ball rolling with a short update.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":60.203,"end":62.839},{"lang":"en-US","text":"fill me in.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":64.539,"end":65.713},{"lang":"pt-BR","text":"atualizar-me sobre o assunto.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":66.013,"end":68.09},{"lang":"en-US","text":"Could you fill me in after the call?","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":68.59,"end":70.579},{"lang":"en-US","text":"sharp.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":72.278,"end":73.174},{"lang":"pt-BR","text":"em ponto.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":73.475,"end":74.582},{"lang":"en-US","text":"The call starts at nine sharp.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":75.082,"end":76.886},{"lang":"en-US","text":"touch base.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":78.586,"end":79.759},{"lang":"pt-BR","text":"fazer um contato breve para alinhar.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":80.059,"end":82.499},{"lang":"en-US","text":"We can touch base on Wednesday.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":82.999,"end":84.934},{"lang":"en-US","text":"on the same page.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":86.634,"end":88.072},{"lang":"pt-BR","text":"com o mesmo entendimento.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":88.372,"end":90.172},{"lang":"en-US","text":"Let us check that we are on the same page.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":90.672,"end":92.947},{"lang":"en-US","text":"take the lead.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":94.647,"end":95.884},{"lang":"pt-BR","text":"assumir a coordenação.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":96.184,"end":97.963},{"lang":"en-US","text":"I can take the lead on the summary.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":98.463,"end":100.558},{"lang":"en-US","text":"keep me posted.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":102.258,"end":103.599},{"lang":"pt-BR","text":"mantenha-me informado.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":103.899,"end":105.53},{"lang":"en-US","text":"Please keep me posted about the reply.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":106.03,"end":108.337},{"lang":"en-US","text":"put it in writing.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":110.037,"end":111.506},{"lang":"pt-BR","text":"registrar por escrito.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":111.806,"end":113.574},{"lang":"en-US","text":"We should put it in writing today.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":114.074,"end":115.997},{"lang":"en-US","text":"plain English.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":117.697,"end":119.02},{"lang":"pt-BR","text":"inglês claro e direto.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":119.32,"end":121.056},{"lang":"en-US","text":"Please explain the decision in plain English.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":121.556,"end":124.342},{"lang":"en-US","text":"idiom.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":126.042,"end":127.066},{"lang":"pt-BR","text":"expressão idiomática.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":127.366,"end":129.081},{"lang":"en-US","text":"This idiom may be unfamiliar to a new colleague.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":129.581,"end":132.504},{"lang":"en-US","text":"next step.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":134.204,"end":135.388},{"lang":"pt-BR","text":"próximo passo.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":135.688,"end":137.061},{"lang":"en-US","text":"Our next step is to draft a short summary.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":137.561,"end":140.379},{"lang":"en-US","text":"get the show on the road.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":142.079,"end":143.695},{"lang":"pt-BR","text":"colocar o plano em execução.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":143.995,"end":146.051},{"lang":"en-US","text":"We can get the show on the road after approval.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":146.551,"end":149.316}],"start":44.727,"end":151.016},{"id":"pronunciation","title":"Pronúncia e repetição","segments":[{"lang":"pt-BR","text":"Agora vamos observar a pronúncia. Os exemplos são modelos falados, não uma avaliação da sua fala. Ouça a parte mais forte e como as palavras se ligam. Repita com calma e depois diga a expressão como um grupo.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":151.016,"end":163.426},{"lang":"pt-BR","text":"Ouça as três palavras como um grupo curto. Mantenha o som final da primeira palavra e ligue a expressão, sem acrescentar uma vogal. O sentido é atualizar alguém sobre um assunto.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":163.926,"end":174.079},{"lang":"en-US","text":"fill me in.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":174.579,"end":175.902},{"lang":"en-US","text":"fill me in.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":177.702,"end":178.726},{"lang":"pt-BR","text":"Dê destaque às palavras que expressam mesmo e página. Nesta conversa, a expressão fala de entendimento comum, não de uma página física.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":180.526,"end":188.69},{"lang":"en-US","text":"on the same page.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":189.19,"end":190.854},{"lang":"en-US","text":"on the same page.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":192.654,"end":193.93},{"lang":"pt-BR","text":"Ouça o final da primeira palavra e o início da segunda. A expressão destaca o horário exato. Repita o grupo e depois acrescente a referência de fuso.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":195.73,"end":204.529},{"lang":"en-US","text":"nine sharp.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":205.029,"end":206.394},{"lang":"en-US","text":"nine sharp.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":208.194,"end":209.238}],"start":151.016,"end":211.038},{"id":"dialogue","title":"Diálogo profissional","segments":[{"lang":"pt-BR","text":"Ouça a conversa completa. Observe o pedido, o esclarecimento e o compromisso final. Cada papel mantém o mesmo padrão de voz durante o diálogo. Depois, consulte a transcrição se precisar de apoio.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":211.038,"end":222.734},{"lang":"en-US","text":"We can get the ball rolling with a short update. Welcome to the project, Riley.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"voice":"af_heart","start":223.234,"end":227.933},{"lang":"en-US","text":"Thanks. Could you fill me in on the decision from yesterday?","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"voice":"am_michael","start":228.333,"end":232.212},{"lang":"en-US","text":"We agreed to draft a one-page summary. Tomorrow’s call starts at nine sharp, London time.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"voice":"af_heart","start":232.612,"end":238.209},{"lang":"en-US","text":"Understood. Can we touch base on Wednesday to check the response?","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"voice":"am_michael","start":238.609,"end":243.192},{"lang":"en-US","text":"Yes. First, let us check that we are on the same page about the summary.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"voice":"af_heart","start":243.592,"end":248.15},{"lang":"en-US","text":"I can take the lead on the first draft and send it today.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"voice":"am_michael","start":248.55,"end":252.262},{"lang":"en-US","text":"Great. Please keep me posted if any information is missing.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"voice":"af_heart","start":252.662,"end":256.107},{"lang":"en-US","text":"I will put it in writing so the team can check the owner and deadline.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"voice":"am_michael","start":256.507,"end":261.094},{"lang":"en-US","text":"Please use plain English. Some colleagues are new to this project.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"voice":"af_heart","start":261.494,"end":265.27},{"lang":"en-US","text":"Of course. If an idiom causes confusion, I will explain it another way.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"voice":"am_michael","start":265.67,"end":271.269},{"lang":"en-US","text":"Our next step is your draft today, followed by my review tomorrow.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"voice":"af_heart","start":271.669,"end":275.518},{"lang":"en-US","text":"Then we can get the show on the road after your approval. I will send the summary today.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"voice":"am_michael","start":275.918,"end":281.849},{"lang":"pt-BR","text":"Em outra escuta, assuma um dos papéis. Pause antes da fala desse personagem e tente responder. Uma resposta diferente também pode ser adequada quando comunica o mesmo objetivo com clareza.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":282.249,"end":293.646}],"start":211.038,"end":294.146},{"id":"practice","title":"Sua vez de responder","segments":[{"lang":"pt-BR","text":"Agora é sua vez. Você ouvirá quatro perguntas. Depois de cada uma haverá uma pausa curta para responder e, em seguida, um modelo possível. Pause o player se precisar de mais tempo. O modelo não é a única resposta correta.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":294.146,"end":307.197},{"lang":"en-US","text":"What does get the ball rolling mean here?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":307.697,"end":309.846},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":314.346,"end":316.167},{"lang":"en-US","text":"It means start the discussion with a short update.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":316.367,"end":319.206},{"lang":"en-US","text":"Could you confirm the call time?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":320.806,"end":322.654},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":327.154,"end":328.975},{"lang":"en-US","text":"The call is tomorrow at nine, London time.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":329.175,"end":331.886},{"lang":"en-US","text":"Who will take the lead on the summary?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":333.486,"end":335.613},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":340.113,"end":341.934},{"lang":"en-US","text":"I will draft the summary today, and Morgan will review it tomorrow.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":342.134,"end":346.028},{"lang":"en-US","text":"How will you avoid confusion?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":347.628,"end":349.488},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":353.988,"end":355.808},{"lang":"en-US","text":"I will use plain English and put the next step in writing.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":356.008,"end":359.296}],"start":294.146,"end":360.896},{"id":"summary","title":"Resumo e aplicação","segments":[{"lang":"pt-BR","text":"Para concluir, escolha três expressões do episódio e use-as em uma mensagem curta. Confira o objetivo, o responsável e o próximo passo. Separe fatos observados de previsões. Volte à aula para fazer os jogos, os exercícios de gramática e a revisão.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":360.896,"end":375.938},{"lang":"pt-BR","text":"Esta é uma atividade de prática. A escuta e a autoavaliação não certificam pronúncia ou proficiência. Peça feedback ao professor e repita um capítulo buscando uma melhoria específica. Obrigado por estudar com o ISM Business.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":376.438,"end":389.994}],"start":360.896,"end":390.494}],"audio":"assets/podcasts/idioms-to-clear-actions-pt.mp3","duration":390.494,"bytes":4686956,"sha256":"7cbaeb74234f40fdc39ba5b09c08cf420b1286ee5dfd9a166c5c6b39f82d1542"},"en":{"label":"English only","chapters":[{"id":"opening","title":"Start with the situation","segments":[{"lang":"en-US","text":"Welcome to an I S M Business audio lesson. This episode uses fictional workplace situations. Listen once for meaning, then return to a chapter and practise aloud. You can pause whenever you need more thinking time. This is synthetic narration, with distinct neural voices for the two dialogue roles.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":0.0,"end":20.425},{"lang":"en-US","text":"Here is your situation.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":20.925,"end":22.475},{"lang":"en-US","text":"A new colleague joins your project team. Explain useful meeting expressions, check understanding and agree on a clear written action.","pauseMs":1300,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":22.975,"end":31.593},{"lang":"en-US","text":"At the end, explain one useful expression, take part in the conversation, and make a clear next step. You do not need to memorize every sentence. Aim to communicate the message in your own words.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":32.893,"end":45.249}],"start":0.0,"end":45.749},{"id":"vocabulary","title":"Vocabulary explained","segments":[{"lang":"en-US","text":"We will build twelve useful expressions. For each one, listen to the expression, understand the meaning, and hear an example. Use the pause after each example to repeat or create a similar sentence.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":45.749,"end":59.07},{"lang":"en-US","text":"get the ball rolling.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":59.57,"end":61.079},{"lang":"en-US","text":"Start an activity or discussion.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":61.379,"end":63.388},{"lang":"en-US","text":"We can get the ball rolling with a short update.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":63.888,"end":66.524},{"lang":"en-US","text":"fill me in.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":68.224,"end":69.397},{"lang":"en-US","text":"Give me the information I have missed.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":69.697,"end":71.865},{"lang":"en-US","text":"Could you fill me in after the call?","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":72.365,"end":74.354},{"lang":"en-US","text":"sharp.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":76.054,"end":76.95},{"lang":"en-US","text":"Exactly at the stated time.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":77.25,"end":79.183},{"lang":"en-US","text":"The call starts at nine sharp.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":79.683,"end":81.487},{"lang":"en-US","text":"touch base.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":83.187,"end":84.36},{"lang":"en-US","text":"Have a brief conversation to check progress.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":84.66,"end":87.264},{"lang":"en-US","text":"We can touch base on Wednesday.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":87.764,"end":89.698},{"lang":"en-US","text":"on the same page.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":91.398,"end":92.836},{"lang":"en-US","text":"Share an understanding of the situation.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":93.136,"end":95.498},{"lang":"en-US","text":"Let us check that we are on the same page.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":95.998,"end":98.272},{"lang":"en-US","text":"take the lead.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":99.972,"end":101.21},{"lang":"en-US","text":"Be the person coordinating an activity.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":101.51,"end":104.222},{"lang":"en-US","text":"I can take the lead on the summary.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":104.722,"end":106.818},{"lang":"en-US","text":"keep me posted.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":108.518,"end":109.859},{"lang":"en-US","text":"Continue to give me updates.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":110.159,"end":112.068},{"lang":"en-US","text":"Please keep me posted about the reply.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":112.568,"end":114.876},{"lang":"en-US","text":"put it in writing.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":116.576,"end":118.045},{"lang":"en-US","text":"Make a written record of an agreement.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":118.345,"end":120.587},{"lang":"en-US","text":"We should put it in writing today.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":121.087,"end":123.01},{"lang":"en-US","text":"plain English.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":124.71,"end":126.033},{"lang":"en-US","text":"Clear language that people can understand.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":126.333,"end":128.886},{"lang":"en-US","text":"Please explain the decision in plain English.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":129.386,"end":132.173},{"lang":"en-US","text":"idiom.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":133.873,"end":134.897},{"lang":"en-US","text":"An expression whose meaning is not simply its separate words.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":135.197,"end":138.942},{"lang":"en-US","text":"This idiom may be unfamiliar to a new colleague.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":139.442,"end":142.366},{"lang":"en-US","text":"next step.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":144.066,"end":145.249},{"lang":"en-US","text":"The action that follows the current one.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":145.549,"end":147.686},{"lang":"en-US","text":"Our next step is to draft a short summary.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":148.186,"end":151.004},{"lang":"en-US","text":"get the show on the road.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":152.704,"end":154.32},{"lang":"en-US","text":"Start carrying out a plan that is ready.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":154.62,"end":156.844},{"lang":"en-US","text":"We can get the show on the road after approval.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":157.344,"end":160.11}],"start":45.749,"end":161.81},{"id":"pronunciation","title":"Pronunciation and repetition","segments":[{"lang":"en-US","text":"Now focus on pronunciation. The examples are spoken models, not a pronunciation score. Listen for the stronger beat and how words join in a phrase. Repeat slowly, then say the whole phrase naturally.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":161.81,"end":175.4},{"lang":"en-US","text":"Listen to the three words as one short group. Keep the final sound of fill and connect it to me. There is no need to translate each word separately.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":175.9,"end":185.051},{"lang":"en-US","text":"fill me in.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":185.551,"end":186.874},{"lang":"en-US","text":"fill me in.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":188.674,"end":189.698},{"lang":"en-US","text":"Make same and page easy to hear. The expression is about shared understanding, not a physical page in this conversation.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":191.498,"end":199.21},{"lang":"en-US","text":"on the same page.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":199.71,"end":201.374},{"lang":"en-US","text":"on the same page.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":203.174,"end":204.45},{"lang":"en-US","text":"Hear the final sound in nine and the beginning of sharp. Sharp makes the exact time important. Repeat the whole group, then add London time.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":206.25,"end":215.198},{"lang":"en-US","text":"nine sharp.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":215.698,"end":217.063},{"lang":"en-US","text":"nine sharp.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":218.863,"end":219.907}],"start":161.81,"end":221.707},{"id":"dialogue","title":"Workplace dialogue","segments":[{"lang":"en-US","text":"Listen to the complete conversation. Notice the request, the clarification and the final commitment. The two roles keep the same delivery throughout. Read the transcript afterwards if you need support.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":221.707,"end":234.432},{"lang":"en-US","text":"We can get the ball rolling with a short update. Welcome to the project, Riley.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"voice":"af_heart","start":234.932,"end":239.631},{"lang":"en-US","text":"Thanks. Could you fill me in on the decision from yesterday?","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"voice":"am_michael","start":240.031,"end":243.91},{"lang":"en-US","text":"We agreed to draft a one-page summary. Tomorrow’s call starts at nine sharp, London time.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"voice":"af_heart","start":244.31,"end":249.907},{"lang":"en-US","text":"Understood. Can we touch base on Wednesday to check the response?","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"voice":"am_michael","start":250.307,"end":254.889},{"lang":"en-US","text":"Yes. First, let us check that we are on the same page about the summary.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"voice":"af_heart","start":255.29,"end":259.847},{"lang":"en-US","text":"I can take the lead on the first draft and send it today.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"voice":"am_michael","start":260.247,"end":263.959},{"lang":"en-US","text":"Great. Please keep me posted if any information is missing.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"voice":"af_heart","start":264.359,"end":267.805},{"lang":"en-US","text":"I will put it in writing so the team can check the owner and deadline.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"voice":"am_michael","start":268.205,"end":272.791},{"lang":"en-US","text":"Please use plain English. Some colleagues are new to this project.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"voice":"af_heart","start":273.191,"end":276.968},{"lang":"en-US","text":"Of course. If an idiom causes confusion, I will explain it another way.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"voice":"am_michael","start":277.368,"end":282.967},{"lang":"en-US","text":"Our next step is your draft today, followed by my review tomorrow.","pauseMs":400,"rate":94,"role":"Morgan","pitch":-1,"voice":"af_heart","start":283.367,"end":287.216},{"lang":"en-US","text":"Then we can get the show on the road after your approval. I will send the summary today.","pauseMs":400,"rate":90,"role":"Riley","pitch":2,"voice":"am_michael","start":287.616,"end":293.547},{"lang":"en-US","text":"Listen again later and take one role. Pause before that person speaks and predict the response. A different answer can still be appropriate if it communicates the same goal clearly.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":293.947,"end":305.233}],"start":221.707,"end":305.733},{"id":"practice","title":"Your turn to respond","segments":[{"lang":"en-US","text":"Your turn. You will hear four prompts. After each prompt there is a short pause for your response, followed by one possible model. Pause the player if you need more time. The model is not the only correct answer.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":305.733,"end":319.145},{"lang":"en-US","text":"What does get the ball rolling mean here?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":319.645,"end":321.795},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":326.295,"end":327.937},{"lang":"en-US","text":"It means start the discussion with a short update.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":328.137,"end":330.977},{"lang":"en-US","text":"Could you confirm the call time?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":332.577,"end":334.425},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":338.925,"end":340.567},{"lang":"en-US","text":"The call is tomorrow at nine, London time.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":340.767,"end":343.479},{"lang":"en-US","text":"Who will take the lead on the summary?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":345.079,"end":347.205},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":351.705,"end":353.348},{"lang":"en-US","text":"I will draft the summary today, and Morgan will review it tomorrow.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":353.548,"end":357.443},{"lang":"en-US","text":"How will you avoid confusion?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":359.043,"end":360.902},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":365.402,"end":367.045},{"lang":"en-US","text":"I will use plain English and put the next step in writing.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":367.245,"end":370.532}],"start":305.733,"end":372.132},{"id":"summary","title":"Recap and application","segments":[{"lang":"en-US","text":"To recap, choose three expressions from the episode and use them in a short message. Check the goal, the person responsible and the next step. Keep observed facts separate from predictions. Return to the lesson for the games, grammar practice and final review.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":372.132,"end":388.579},{"lang":"en-US","text":"This is a practice activity. Listening and self-assessment do not certify pronunciation or proficiency. Ask your teacher for feedback and repeat one chapter with a specific improvement in mind. Thank you for studying with I S M Business.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":389.079,"end":404.992}],"start":372.132,"end":405.492}],"audio":"assets/podcasts/idioms-to-clear-actions-en.mp3","duration":405.492,"bytes":4866956,"sha256":"b0baf687459a2dd4913e7d52615566397efdd5c2b29ccd3c1cad559a2ab41dbd"}},"disclosure":"Vozes neurais sintetizadas com Kokoro: Dora (português), Heart e Michael (inglês). Cada personagem mantém uma voz própria. Não são gravações de atores."},{"id":"budget-and-workflow","title":"Operações: explicar orçamento, fluxo e indicadores","lesson":"business-practice.html#budget-and-workflow/0","image":"assets/reference-budget-workflow.svg","versions":{"pt":{"label":"Português + exemplos em inglês","chapters":[{"id":"opening","title":"Comece pelo contexto","segments":[{"lang":"pt-BR","text":"Bem-vindo a uma aula em áudio do ISM Business. Este episódio usa situações profissionais fictícias. Na primeira vez, acompanhe o sentido. Depois retorne aos capítulos e pratique em voz alta. Pause sempre que precisar de mais tempo. A narração é sintetizada. Os personagens usam vozes neurais diferentes em inglês.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":0.0,"end":18.651},{"lang":"pt-BR","text":"Conheça a situação que vamos praticar.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":19.151,"end":21.719},{"lang":"en-US","text":"Your fictional team is reviewing a pilot service. Use the planning figures and process information to propose a small test. No spending decision has been approved.","pauseMs":1300,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":22.219,"end":33.261},{"lang":"pt-BR","text":"Ao final, explique uma expressão útil, participe da conversa e deixe claro um próximo passo. Você não precisa decorar todas as frases. O objetivo é comunicar a mensagem com suas próprias palavras.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":34.561,"end":46.651}],"start":0.0,"end":47.151},{"id":"vocabulary","title":"Vocabulário explicado","segments":[{"lang":"pt-BR","text":"Vamos trabalhar doze expressões úteis. Para cada uma, ouça o termo, compreenda o sentido e acompanhe uma frase de exemplo. Use a pausa depois do exemplo para repetir ou criar uma frase semelhante.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":47.151,"end":58.667},{"lang":"en-US","text":"budget.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":59.167,"end":60.17},{"lang":"pt-BR","text":"orçamento.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":60.47,"end":61.62},{"lang":"en-US","text":"The pilot budget is still a draft.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":62.12,"end":64.214},{"lang":"en-US","text":"cash flow.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":65.914,"end":67.13},{"lang":"pt-BR","text":"fluxo de caixa.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":67.43,"end":68.931},{"lang":"en-US","text":"The cash flow forecast tracks money coming in and going out.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":69.431,"end":72.698},{"lang":"en-US","text":"revenue.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":74.398,"end":75.465},{"lang":"pt-BR","text":"receita.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":75.765,"end":76.882},{"lang":"en-US","text":"Pilot revenue was twenty thousand dollars.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":77.382,"end":80.105},{"lang":"en-US","text":"profit.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":81.805,"end":82.872},{"lang":"pt-BR","text":"lucro.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":83.172,"end":84.044},{"lang":"en-US","text":"Pilot profit was three thousand dollars after recorded costs.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":84.544,"end":88.552},{"lang":"en-US","text":"KPI.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":90.252,"end":91.362},{"lang":"pt-BR","text":"indicador-chave de desempenho.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":91.662,"end":93.825},{"lang":"en-US","text":"Our KPI is the percentage of orders delivered on time.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":94.325,"end":98.078},{"lang":"en-US","text":"workflow.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":99.778,"end":100.906},{"lang":"pt-BR","text":"fluxo de trabalho.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":101.206,"end":102.793},{"lang":"en-US","text":"The workflow has an approval step.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":103.293,"end":105.491},{"lang":"en-US","text":"spreadsheet.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":107.191,"end":108.343},{"lang":"pt-BR","text":"planilha.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":108.643,"end":109.656},{"lang":"en-US","text":"The spreadsheet separates results from estimates.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":110.156,"end":113.007},{"lang":"en-US","text":"outsource.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":114.707,"end":115.752},{"lang":"pt-BR","text":"terceirizar.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":116.052,"end":117.255},{"lang":"en-US","text":"We may outsource a small support task.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":117.755,"end":120.092},{"lang":"en-US","text":"B2B.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":121.792,"end":122.966},{"lang":"pt-BR","text":"entre empresas.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":123.266,"end":124.596},{"lang":"en-US","text":"The B2B service is sold to other companies.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":125.096,"end":128.287},{"lang":"en-US","text":"B2C.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":129.987,"end":131.203},{"lang":"pt-BR","text":"da empresa ao consumidor.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":131.503,"end":133.474},{"lang":"en-US","text":"The B2C service is sold directly to individual customers.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":133.974,"end":138.356},{"lang":"en-US","text":"asset.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":140.056,"end":141.102},{"lang":"pt-BR","text":"ativo; recurso com valor para a organização.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":141.402,"end":144.296},{"lang":"en-US","text":"The server is an asset used by the team.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":144.796,"end":147.392},{"lang":"en-US","text":"target.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":149.092,"end":150.073},{"lang":"pt-BR","text":"meta.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":150.373,"end":151.258},{"lang":"en-US","text":"The target is ninety-five percent on-time delivery.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":151.758,"end":154.994}],"start":47.151,"end":156.694},{"id":"pronunciation","title":"Pronúncia e repetição","segments":[{"lang":"pt-BR","text":"Agora vamos observar a pronúncia. Os exemplos são modelos falados, não uma avaliação da sua fala. Ouça a parte mais forte e como as palavras se ligam. Repita com calma e depois diga a expressão como um grupo.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":156.694,"end":169.104},{"lang":"pt-BR","text":"A parte mais forte da palavra está no início. Preste atenção ao final e evite acrescentar uma vogal depois da última consoante.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":169.604,"end":177.473},{"lang":"en-US","text":"budget.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":177.973,"end":179.104},{"lang":"en-US","text":"budget.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":180.904,"end":181.714},{"lang":"pt-BR","text":"As duas palavras têm destaque no início. Além de pronunciar, lembre que receita e lucro são medidas diferentes. Ouça, pause e repita o grupo completo.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":183.514,"end":192.686},{"lang":"en-US","text":"revenue and profit.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":193.186,"end":195.196},{"lang":"en-US","text":"revenue and profit.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":196.996,"end":198.546},{"lang":"pt-BR","text":"Diga as letras separadamente em inglês. Depois explique o que está sendo medido. A clareza da explicação é mais importante que o uso da sigla.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":200.346,"end":208.612},{"lang":"en-US","text":"K. P. I..","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":209.112,"end":211.369},{"lang":"en-US","text":"K. P. I..","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":213.169,"end":215.108},{"lang":"en-US","text":"K. P. I. Business to business. Business to consumer.","pauseMs":1800,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":216.908,"end":221.143}],"start":156.694,"end":222.943},{"id":"dialogue","title":"Diálogo profissional","segments":[{"lang":"pt-BR","text":"Ouça a conversa completa. Observe o pedido, o esclarecimento e o compromisso final. Cada papel mantém o mesmo padrão de voz durante o diálogo. Depois, consulte a transcrição se precisar de apoio.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":222.943,"end":234.639},{"lang":"en-US","text":"Let us review the pilot budget. It is still a draft, so no new spending is approved.","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"voice":"af_heart","start":235.139,"end":240.409},{"lang":"en-US","text":"The spreadsheet separates last month’s results from next month’s estimates.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"voice":"am_michael","start":240.809,"end":245.532},{"lang":"en-US","text":"What revenue did the pilot generate last month?","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"voice":"af_heart","start":245.932,"end":248.739},{"lang":"en-US","text":"Revenue was twenty thousand dollars, and profit was three thousand after recorded costs.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"voice":"am_michael","start":249.139,"end":255.484},{"lang":"en-US","text":"That does not tell us when customers pay. What does the cash flow forecast show?","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"voice":"af_heart","start":255.884,"end":260.556},{"lang":"en-US","text":"Some payments are expected next month. The cash flow forecast keeps that timing visible.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"voice":"am_michael","start":260.956,"end":267.228},{"lang":"en-US","text":"Our delivery KPI was ninety percent on time. The target is ninety-five percent.","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"voice":"af_heart","start":267.628,"end":273.173},{"lang":"en-US","text":"The workflow has a long approval step. We may outsource one small support task as a test.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"voice":"am_michael","start":273.574,"end":280.072},{"lang":"en-US","text":"Is this for our B2B service, which sells to other companies?","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"voice":"af_heart","start":280.472,"end":284.515},{"lang":"en-US","text":"Yes. The B2C service for individual customers is outside this pilot.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"voice":"am_michael","start":284.915,"end":290.627},{"lang":"en-US","text":"The existing server is an asset we can use. Please check the test cost before proposing a purchase.","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"voice":"af_heart","start":291.027,"end":297.574},{"lang":"en-US","text":"I will send the draft on Thursday, including the KPI, target and approval request.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"voice":"am_michael","start":297.974,"end":304.189},{"lang":"pt-BR","text":"Em outra escuta, assuma um dos papéis. Pause antes da fala desse personagem e tente responder. Uma resposta diferente também pode ser adequada quando comunica o mesmo objetivo com clareza.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":304.589,"end":315.987}],"start":222.943,"end":316.487},{"id":"practice","title":"Sua vez de responder","segments":[{"lang":"pt-BR","text":"Agora é sua vez. Você ouvirá quatro perguntas. Depois de cada uma haverá uma pausa curta para responder e, em seguida, um modelo possível. Pause o player se precisar de mais tempo. O modelo não é a única resposta correta.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":316.487,"end":329.537},{"lang":"en-US","text":"Are revenue and profit the same here?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":330.037,"end":332.228},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":336.728,"end":338.549},{"lang":"en-US","text":"No. Revenue was twenty thousand dollars, while profit was three thousand after recorded costs.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":338.749,"end":345.103},{"lang":"en-US","text":"What does our KPI measure?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":346.703,"end":348.478},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":352.978,"end":354.799},{"lang":"en-US","text":"It measures the percentage of orders delivered on time. The target is ninety-five percent.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":354.999,"end":360.887},{"lang":"en-US","text":"What change are you proposing?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":362.487,"end":364.22},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":368.72,"end":370.541},{"lang":"en-US","text":"We may outsource a small support task to test a shorter workflow.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":370.741,"end":374.89},{"lang":"en-US","text":"What will you do next?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":376.49,"end":377.911},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":382.411,"end":384.232},{"lang":"en-US","text":"I will send the draft and request approval on Thursday.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":384.432,"end":387.657}],"start":316.487,"end":389.257},{"id":"summary","title":"Resumo e aplicação","segments":[{"lang":"pt-BR","text":"Para concluir, escolha três expressões do episódio e use-as em uma mensagem curta. Confira o objetivo, o responsável e o próximo passo. Separe fatos observados de previsões. Volte à aula para fazer os jogos, os exercícios de gramática e a revisão.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":389.257,"end":404.299},{"lang":"pt-BR","text":"Esta é uma atividade de prática. A escuta e a autoavaliação não certificam pronúncia ou proficiência. Peça feedback ao professor e repita um capítulo buscando uma melhoria específica. Obrigado por estudar com o ISM Business.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":404.799,"end":418.355}],"start":389.257,"end":418.855}],"audio":"assets/podcasts/budget-and-workflow-pt.mp3","duration":418.855,"bytes":5027372,"sha256":"8b0a2577919aea7b84685bf47a245ddb13484c61b8f82f40fedce38a967a3d7e"},"en":{"label":"English only","chapters":[{"id":"opening","title":"Start with the situation","segments":[{"lang":"en-US","text":"Welcome to an I S M Business audio lesson. This episode uses fictional workplace situations. Listen once for meaning, then return to a chapter and practise aloud. You can pause whenever you need more thinking time. This is synthetic narration, with distinct neural voices for the two dialogue roles.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":0.0,"end":20.425},{"lang":"en-US","text":"Here is your situation.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":20.925,"end":22.475},{"lang":"en-US","text":"Your fictional team is reviewing a pilot service. Use the planning figures and process information to propose a small test. No spending decision has been approved.","pauseMs":1300,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":22.975,"end":34.016},{"lang":"en-US","text":"At the end, explain one useful expression, take part in the conversation, and make a clear next step. You do not need to memorize every sentence. Aim to communicate the message in your own words.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":35.316,"end":47.672}],"start":0.0,"end":48.172},{"id":"vocabulary","title":"Vocabulary explained","segments":[{"lang":"en-US","text":"We will build twelve useful expressions. For each one, listen to the expression, understand the meaning, and hear an example. Use the pause after each example to repeat or create a similar sentence.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":48.172,"end":61.493},{"lang":"en-US","text":"budget.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":61.993,"end":62.996},{"lang":"en-US","text":"A plan for how much money can be used.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":63.296,"end":65.667},{"lang":"en-US","text":"The pilot budget is still a draft.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":66.167,"end":68.261},{"lang":"en-US","text":"cash flow.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":69.961,"end":71.177},{"lang":"en-US","text":"Money coming into and going out of an operation over time.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":71.477,"end":75.188},{"lang":"en-US","text":"The cash flow forecast tracks money coming in and going out.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":75.688,"end":78.956},{"lang":"en-US","text":"revenue.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":80.656,"end":81.722},{"lang":"en-US","text":"Income generated by the business activity in this example.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":82.022,"end":85.926},{"lang":"en-US","text":"Pilot revenue was twenty thousand dollars.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":86.426,"end":89.148},{"lang":"en-US","text":"profit.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":90.848,"end":91.915},{"lang":"en-US","text":"The amount left after the recorded costs in this example.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":92.215,"end":95.737},{"lang":"en-US","text":"Pilot profit was three thousand dollars after recorded costs.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":96.237,"end":100.246},{"lang":"en-US","text":"KPI.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":101.946,"end":103.055},{"lang":"en-US","text":"A selected measure used to check performance against a goal.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":103.355,"end":106.992},{"lang":"en-US","text":"Our KPI is the percentage of orders delivered on time.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":107.492,"end":111.246},{"lang":"en-US","text":"workflow.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":112.946,"end":114.074},{"lang":"en-US","text":"The sequence of steps used to complete work.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":114.374,"end":116.895},{"lang":"en-US","text":"The workflow has an approval step.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":117.395,"end":119.593},{"lang":"en-US","text":"spreadsheet.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":121.293,"end":122.445},{"lang":"en-US","text":"A document that organizes data in rows and columns.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":122.745,"end":126.277},{"lang":"en-US","text":"The spreadsheet separates results from estimates.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":126.777,"end":129.628},{"lang":"en-US","text":"outsource.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":131.328,"end":132.373},{"lang":"en-US","text":"Ask an outside provider to perform a task.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":132.673,"end":135.511},{"lang":"en-US","text":"We may outsource a small support task.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":136.011,"end":138.348},{"lang":"en-US","text":"B2B.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":140.048,"end":141.222},{"lang":"en-US","text":"Business to business: selling to another company.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":141.522,"end":144.617},{"lang":"en-US","text":"The B2B service is sold to other companies.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":145.117,"end":148.308},{"lang":"en-US","text":"B2C.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":150.008,"end":151.224},{"lang":"en-US","text":"Business to consumer: selling to an individual customer.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":151.524,"end":155.238},{"lang":"en-US","text":"The B2C service is sold directly to individual customers.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":155.738,"end":160.12},{"lang":"en-US","text":"asset.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":161.82,"end":162.866},{"lang":"en-US","text":"A resource with value that an organization uses or controls.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":163.166,"end":167.43},{"lang":"en-US","text":"The server is an asset used by the team.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":167.93,"end":170.526},{"lang":"en-US","text":"target.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":172.226,"end":173.208},{"lang":"en-US","text":"The level of performance the team wants to reach.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":173.508,"end":176.23},{"lang":"en-US","text":"The target is ninety-five percent on-time delivery.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":176.73,"end":179.966}],"start":48.172,"end":181.666},{"id":"pronunciation","title":"Pronunciation and repetition","segments":[{"lang":"en-US","text":"Now focus on pronunciation. The examples are spoken models, not a pronunciation score. Listen for the stronger beat and how words join in a phrase. Repeat slowly, then say the whole phrase naturally.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":181.666,"end":195.256},{"lang":"en-US","text":"The strongest beat is at the beginning of budget. Listen to the ending. Do not add an extra vowel after the final consonant.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":195.756,"end":203.532},{"lang":"en-US","text":"budget.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":204.032,"end":205.163},{"lang":"en-US","text":"budget.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":206.963,"end":207.774},{"lang":"en-US","text":"Both revenue and profit have a strong first beat. Keep the two measures separate when you explain the figures. Listen, pause, and say the complete group.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":209.574,"end":219.18},{"lang":"en-US","text":"revenue and profit.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":219.68,"end":221.69},{"lang":"en-US","text":"revenue and profit.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":223.49,"end":225.041},{"lang":"en-US","text":"Say the letters individually. Then explain the measure in ordinary words. A clear explanation matters more than using an abbreviation.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":226.841,"end":235.63},{"lang":"en-US","text":"K. P. I..","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":236.13,"end":238.387},{"lang":"en-US","text":"K. P. I..","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":240.187,"end":242.126},{"lang":"en-US","text":"K. P. I. Business to business. Business to consumer.","pauseMs":1800,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":243.926,"end":248.161}],"start":181.666,"end":249.961},{"id":"dialogue","title":"Workplace dialogue","segments":[{"lang":"en-US","text":"Listen to the complete conversation. Notice the request, the clarification and the final commitment. The two roles keep the same delivery throughout. Read the transcript afterwards if you need support.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":249.961,"end":262.686},{"lang":"en-US","text":"Let us review the pilot budget. It is still a draft, so no new spending is approved.","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"voice":"af_heart","start":263.186,"end":268.456},{"lang":"en-US","text":"The spreadsheet separates last month’s results from next month’s estimates.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"voice":"am_michael","start":268.856,"end":273.579},{"lang":"en-US","text":"What revenue did the pilot generate last month?","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"voice":"af_heart","start":273.979,"end":276.786},{"lang":"en-US","text":"Revenue was twenty thousand dollars, and profit was three thousand after recorded costs.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"voice":"am_michael","start":277.186,"end":283.531},{"lang":"en-US","text":"That does not tell us when customers pay. What does the cash flow forecast show?","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"voice":"af_heart","start":283.931,"end":288.603},{"lang":"en-US","text":"Some payments are expected next month. The cash flow forecast keeps that timing visible.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"voice":"am_michael","start":289.003,"end":295.275},{"lang":"en-US","text":"Our delivery KPI was ninety percent on time. The target is ninety-five percent.","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"voice":"af_heart","start":295.675,"end":301.221},{"lang":"en-US","text":"The workflow has a long approval step. We may outsource one small support task as a test.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"voice":"am_michael","start":301.621,"end":308.119},{"lang":"en-US","text":"Is this for our B2B service, which sells to other companies?","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"voice":"af_heart","start":308.519,"end":312.562},{"lang":"en-US","text":"Yes. The B2C service for individual customers is outside this pilot.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"voice":"am_michael","start":312.962,"end":318.674},{"lang":"en-US","text":"The existing server is an asset we can use. Please check the test cost before proposing a purchase.","pauseMs":400,"rate":94,"role":"Dana","pitch":-1,"voice":"af_heart","start":319.074,"end":325.621},{"lang":"en-US","text":"I will send the draft on Thursday, including the KPI, target and approval request.","pauseMs":400,"rate":90,"role":"Sam","pitch":2,"voice":"am_michael","start":326.021,"end":332.237},{"lang":"en-US","text":"Listen again later and take one role. Pause before that person speaks and predict the response. A different answer can still be appropriate if it communicates the same goal clearly.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":332.637,"end":343.923}],"start":249.961,"end":344.423},{"id":"practice","title":"Your turn to respond","segments":[{"lang":"en-US","text":"Your turn. You will hear four prompts. After each prompt there is a short pause for your response, followed by one possible model. Pause the player if you need more time. The model is not the only correct answer.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":344.423,"end":357.835},{"lang":"en-US","text":"Are revenue and profit the same here?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":358.335,"end":360.526},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":365.026,"end":366.669},{"lang":"en-US","text":"No. Revenue was twenty thousand dollars, while profit was three thousand after recorded costs.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":366.869,"end":373.223},{"lang":"en-US","text":"What does our KPI measure?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":374.822,"end":376.598},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":381.098,"end":382.74},{"lang":"en-US","text":"It measures the percentage of orders delivered on time. The target is ninety-five percent.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":382.94,"end":388.829},{"lang":"en-US","text":"What change are you proposing?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":390.429,"end":392.162},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":396.662,"end":398.305},{"lang":"en-US","text":"We may outsource a small support task to test a shorter workflow.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":398.505,"end":402.654},{"lang":"en-US","text":"What will you do next?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":404.254,"end":405.675},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":410.175,"end":411.818},{"lang":"en-US","text":"I will send the draft and request approval on Thursday.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":412.018,"end":415.242}],"start":344.423,"end":416.842},{"id":"summary","title":"Recap and application","segments":[{"lang":"en-US","text":"To recap, choose three expressions from the episode and use them in a short message. Check the goal, the person responsible and the next step. Keep observed facts separate from predictions. Return to the lesson for the games, grammar practice and final review.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":416.842,"end":433.29},{"lang":"en-US","text":"This is a practice activity. Listening and self-assessment do not certify pronunciation or proficiency. Ask your teacher for feedback and repeat one chapter with a specific improvement in mind. Thank you for studying with I S M Business.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":433.79,"end":449.702}],"start":416.842,"end":450.202}],"audio":"assets/podcasts/budget-and-workflow-en.mp3","duration":450.202,"bytes":5403500,"sha256":"3cb5967158bda0d8988ba4048ab269ef950f6d2b8f988d50206ce0e25e8cffa6"}},"disclosure":"Vozes neurais sintetizadas com Kokoro: Dora (português), Heart e Michael (inglês). Cada personagem mantém uma voz própria. Não são gravações de atores."},{"id":"supplier-delivery-agreement","title":"Fornecedores: confirmar preço, documentos e entrega","lesson":"business-practice.html#supplier-delivery-agreement/0","image":"assets/reference-supplier-delivery.svg","versions":{"pt":{"label":"Português + exemplos em inglês","chapters":[{"id":"opening","title":"Comece pelo contexto","segments":[{"lang":"pt-BR","text":"Bem-vindo a uma aula em áudio do ISM Business. Este episódio usa situações profissionais fictícias. Na primeira vez, acompanhe o sentido. Depois retorne aos capítulos e pratique em voz alta. Pause sempre que precisar de mais tempo. A narração é sintetizada. Os personagens usam vozes neurais diferentes em inglês.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":0.0,"end":18.651},{"lang":"pt-BR","text":"Conheça a situação que vamos praticar.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":19.151,"end":21.719},{"lang":"en-US","text":"Your fictional team needs sample units for a distributor. A supplier has sent a quotation, but freight and the delivery estimate need clarification before an order is approved.","pauseMs":1300,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":22.219,"end":34.103},{"lang":"pt-BR","text":"Ao final, explique uma expressão útil, participe da conversa e deixe claro um próximo passo. Você não precisa decorar todas as frases. O objetivo é comunicar a mensagem com suas próprias palavras.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":35.403,"end":47.493}],"start":0.0,"end":47.993},{"id":"vocabulary","title":"Vocabulário explicado","segments":[{"lang":"pt-BR","text":"Vamos trabalhar doze expressões úteis. Para cada uma, ouça o termo, compreenda o sentido e acompanhe uma frase de exemplo. Use a pausa depois do exemplo para repetir ou criar uma frase semelhante.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":47.993,"end":59.509},{"lang":"en-US","text":"supply chain.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":60.009,"end":61.332},{"lang":"pt-BR","text":"cadeia de suprimentos.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":61.632,"end":63.411},{"lang":"en-US","text":"Our supply chain includes two suppliers and a carrier.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":63.911,"end":67.209},{"lang":"en-US","text":"supplier.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":68.909,"end":70.04},{"lang":"pt-BR","text":"fornecedor.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":70.34,"end":71.513},{"lang":"en-US","text":"The supplier has sent a quotation.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":72.013,"end":74.161},{"lang":"en-US","text":"quotation.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":75.861,"end":77.034},{"lang":"pt-BR","text":"cotação comercial.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":77.334,"end":78.973},{"lang":"en-US","text":"The quotation does not include freight.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":79.473,"end":81.822},{"lang":"en-US","text":"invoice.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":83.522,"end":84.546},{"lang":"pt-BR","text":"fatura.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":84.846,"end":85.869},{"lang":"en-US","text":"The invoice must show the agreed order details.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":86.369,"end":89.081},{"lang":"en-US","text":"freight.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":90.781,"end":91.74},{"lang":"pt-BR","text":"frete; transporte de carga.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":92.04,"end":94.011},{"lang":"en-US","text":"Freight will be listed separately.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":94.511,"end":96.382},{"lang":"en-US","text":"shipment.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":98.082,"end":99.148},{"lang":"pt-BR","text":"remessa.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":99.448,"end":100.513},{"lang":"en-US","text":"The shipment will contain sample units.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":101.013,"end":103.373},{"lang":"en-US","text":"lead time.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":105.073,"end":106.204},{"lang":"pt-BR","text":"prazo entre o pedido confirmado e a entrega neste cenário.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":106.504,"end":110.001},{"lang":"en-US","text":"The lead time estimate is ten working days after order confirmation.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":110.501,"end":114.96},{"lang":"en-US","text":"purchase order.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":116.66,"end":117.983},{"lang":"pt-BR","text":"pedido de compra.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":118.282,"end":119.743},{"lang":"en-US","text":"The purchase order requires internal approval.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":120.243,"end":123.103},{"lang":"en-US","text":"stakeholder.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":124.803,"end":125.934},{"lang":"pt-BR","text":"parte interessada.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":126.234,"end":127.746},{"lang":"en-US","text":"Each stakeholder needs the confirmed delivery information.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":128.246,"end":131.874},{"lang":"en-US","text":"procurement.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":133.574,"end":134.79},{"lang":"pt-BR","text":"área ou processo de compras.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":135.09,"end":137.125},{"lang":"en-US","text":"Procurement will review the quotation.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":137.625,"end":139.93},{"lang":"en-US","text":"win-win.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":141.631,"end":142.719},{"lang":"pt-BR","text":"vantajoso para ambas as partes.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":143.018,"end":145.276},{"lang":"en-US","text":"A smaller sample order could be a win-win solution.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":145.776,"end":148.926},{"lang":"en-US","text":"close a deal.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":150.626,"end":151.842},{"lang":"pt-BR","text":"fechar um negócio.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":152.142,"end":153.547},{"lang":"en-US","text":"We cannot close a deal before approval.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":154.047,"end":156.291}],"start":47.993,"end":157.991},{"id":"pronunciation","title":"Pronúncia e repetição","segments":[{"lang":"pt-BR","text":"Agora vamos observar a pronúncia. Os exemplos são modelos falados, não uma avaliação da sua fala. Ouça a parte mais forte e como as palavras se ligam. Repita com calma e depois diga a expressão como um grupo.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":157.991,"end":170.401},{"lang":"pt-BR","text":"Ouça a semelhança com as palavras inglesas que significam atrasado e esperar. As letras G e H não têm som próprio nesta palavra. Escute o modelo e repita.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":170.901,"end":180.266},{"lang":"en-US","text":"freight.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":180.766,"end":181.854},{"lang":"en-US","text":"freight.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":183.654,"end":184.474},{"lang":"pt-BR","text":"A palavra para cotação tem destaque no meio. A palavra para fatura tem destaque no início. Ouça o contraste e diferencie também a função dos documentos.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":186.274,"end":195.093},{"lang":"en-US","text":"quotation and invoice.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":195.593,"end":197.538},{"lang":"en-US","text":"quotation and invoice.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":199.338,"end":200.897},{"lang":"pt-BR","text":"A parte mais forte fica no meio da palavra. Comece de modo leve e torne o trecho central mais claro. Depois use a palavra em uma frase completa.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":202.697,"end":211.261},{"lang":"en-US","text":"procurement.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":211.761,"end":213.148},{"lang":"en-US","text":"procurement.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":214.948,"end":216.014},{"lang":"en-US","text":"Freight. Late. Wait. Procurement will review the quotation.","pauseMs":1800,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":217.814,"end":221.658}],"start":157.991,"end":223.458},{"id":"dialogue","title":"Diálogo profissional","segments":[{"lang":"pt-BR","text":"Ouça a conversa completa. Observe o pedido, o esclarecimento e o compromisso final. Cada papel mantém o mesmo padrão de voz durante o diálogo. Depois, consulte a transcrição se precisar de apoio.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":223.458,"end":235.154},{"lang":"en-US","text":"Our supply chain review shows a delay in one component. Can we discuss the sample order?","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"voice":"af_heart","start":235.654,"end":241.586},{"lang":"en-US","text":"Yes. Is the supplier able to provide twenty sample units?","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"voice":"am_michael","start":241.986,"end":246.306},{"lang":"en-US","text":"The quotation covers twenty units, but it does not include freight.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"voice":"af_heart","start":246.706,"end":250.717},{"lang":"en-US","text":"Please list freight separately so procurement can compare the total cost.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"voice":"am_michael","start":251.117,"end":255.832},{"lang":"en-US","text":"The estimated lead time is ten working days after order confirmation. It is not yet a guaranteed date.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"voice":"af_heart","start":256.232,"end":263.41},{"lang":"en-US","text":"Understood. We cannot send the purchase order before internal approval.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"voice":"am_michael","start":263.81,"end":268.76},{"lang":"en-US","text":"Once the order is confirmed, the shipment will contain only the sample units.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"voice":"af_heart","start":269.16,"end":274.087},{"lang":"en-US","text":"Please make sure the invoice shows the agreed unit price and the separate freight charge.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"voice":"am_michael","start":274.487,"end":280.119},{"lang":"en-US","text":"I will send the revised quotation tomorrow. Which stakeholder should receive the delivery update?","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"voice":"af_heart","start":280.519,"end":286.035},{"lang":"en-US","text":"Our procurement contact should receive it. A small sample order could be a win-win solution before a larger commitment.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"voice":"am_michael","start":286.435,"end":295.132},{"lang":"en-US","text":"That makes sense. We can close a deal only after the price and approval are confirmed.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"voice":"af_heart","start":295.532,"end":300.526},{"lang":"en-US","text":"Agreed. Send the price, freight and delivery estimate in writing tomorrow, and procurement will review them.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"voice":"am_michael","start":300.926,"end":308.482},{"lang":"pt-BR","text":"Em outra escuta, assuma um dos papéis. Pause antes da fala desse personagem e tente responder. Uma resposta diferente também pode ser adequada quando comunica o mesmo objetivo com clareza.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":308.882,"end":320.28}],"start":223.458,"end":320.78},{"id":"practice","title":"Sua vez de responder","segments":[{"lang":"pt-BR","text":"Agora é sua vez. Você ouvirá quatro perguntas. Depois de cada uma haverá uma pausa curta para responder e, em seguida, um modelo possível. Pause o player se precisar de mais tempo. O modelo não é a única resposta correta.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":320.78,"end":333.83},{"lang":"en-US","text":"Does your quotation include every cost?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":334.33,"end":336.817},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":341.317,"end":343.138},{"lang":"en-US","text":"Could you confirm whether freight is included and list it separately?","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":343.338,"end":347.275},{"lang":"en-US","text":"Can you guarantee delivery in ten days?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":348.875,"end":351.329},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":355.829,"end":357.65},{"lang":"en-US","text":"The current estimate is ten working days after order confirmation; I cannot guarantee a date yet.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":357.85,"end":364.262},{"lang":"en-US","text":"Can we send the purchase order now?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":365.862,"end":367.828},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":372.328,"end":374.148},{"lang":"en-US","text":"Not yet. Procurement must review the revised quotation and approve the order first.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":374.348,"end":379.947},{"lang":"en-US","text":"What should we confirm tomorrow?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":381.547,"end":383.354},{"lang":"pt-BR","text":"Uma resposta possível é:","pauseMs":200,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":387.854,"end":389.674},{"lang":"en-US","text":"Please confirm the price, freight and delivery estimate in writing tomorrow.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":389.874,"end":394.58}],"start":320.78,"end":396.18},{"id":"summary","title":"Resumo e aplicação","segments":[{"lang":"pt-BR","text":"Para concluir, escolha três expressões do episódio e use-as em uma mensagem curta. Confira o objetivo, o responsável e o próximo passo. Separe fatos observados de previsões. Volte à aula para fazer os jogos, os exercícios de gramática e a revisão.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":396.18,"end":411.222},{"lang":"pt-BR","text":"Esta é uma atividade de prática. A escuta e a autoavaliação não certificam pronúncia ou proficiência. Peça feedback ao professor e repita um capítulo buscando uma melhoria específica. Obrigado por estudar com o ISM Business.","pauseMs":500,"rate":98,"role":"narrator","pitch":0,"voice":"pf_dora","start":411.722,"end":425.278}],"start":396.18,"end":425.778}],"audio":"assets/podcasts/supplier-delivery-agreement-pt.mp3","duration":425.778,"bytes":5110316,"sha256":"6de730b6eb18e91bfa002ba3fcf1f3522689d2baabcfe8a5ed5174ba4b406a4f"},"en":{"label":"English only","chapters":[{"id":"opening","title":"Start with the situation","segments":[{"lang":"en-US","text":"Welcome to an I S M Business audio lesson. This episode uses fictional workplace situations. Listen once for meaning, then return to a chapter and practise aloud. You can pause whenever you need more thinking time. This is synthetic narration, with distinct neural voices for the two dialogue roles.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":0.0,"end":20.425},{"lang":"en-US","text":"Here is your situation.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":20.925,"end":22.475},{"lang":"en-US","text":"Your fictional team needs sample units for a distributor. A supplier has sent a quotation, but freight and the delivery estimate need clarification before an order is approved.","pauseMs":1300,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":22.975,"end":34.858},{"lang":"en-US","text":"At the end, explain one useful expression, take part in the conversation, and make a clear next step. You do not need to memorize every sentence. Aim to communicate the message in your own words.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":36.158,"end":48.514}],"start":0.0,"end":49.014},{"id":"vocabulary","title":"Vocabulary explained","segments":[{"lang":"en-US","text":"We will build twelve useful expressions. For each one, listen to the expression, understand the meaning, and hear an example. Use the pause after each example to repeat or create a similar sentence.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":49.014,"end":62.335},{"lang":"en-US","text":"supply chain.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":62.835,"end":64.158},{"lang":"en-US","text":"The connected organizations and processes that move goods to customers.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":64.458,"end":68.927},{"lang":"en-US","text":"Our supply chain includes two suppliers and a carrier.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":69.427,"end":72.726},{"lang":"en-US","text":"supplier.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":74.426,"end":75.557},{"lang":"en-US","text":"A person or company providing goods or services.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":75.857,"end":79.272},{"lang":"en-US","text":"The supplier has sent a quotation.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":79.772,"end":81.92},{"lang":"en-US","text":"quotation.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":83.62,"end":84.793},{"lang":"en-US","text":"A statement of proposed prices and conditions.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":85.093,"end":88.049},{"lang":"en-US","text":"The quotation does not include freight.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":88.549,"end":90.898},{"lang":"en-US","text":"invoice.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":92.598,"end":93.622},{"lang":"en-US","text":"A document requesting payment for an agreed transaction.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":93.922,"end":97.431},{"lang":"en-US","text":"The invoice must show the agreed order details.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":97.931,"end":100.643},{"lang":"en-US","text":"freight.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":102.343,"end":103.303},{"lang":"en-US","text":"The transportation of goods, or its charge in this example.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":103.603,"end":107.091},{"lang":"en-US","text":"Freight will be listed separately.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":107.591,"end":109.461},{"lang":"en-US","text":"shipment.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":111.161,"end":112.228},{"lang":"en-US","text":"A group of goods being transported.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":112.528,"end":114.666},{"lang":"en-US","text":"The shipment will contain sample units.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":115.166,"end":117.526},{"lang":"en-US","text":"lead time.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":119.226,"end":120.357},{"lang":"en-US","text":"In this scenario, the estimated period from order confirmation to delivery.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":120.657,"end":125.756},{"lang":"en-US","text":"The lead time estimate is ten working days after order confirmation.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":126.256,"end":130.715},{"lang":"en-US","text":"purchase order.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":132.415,"end":133.738},{"lang":"en-US","text":"A document through which a buyer places an order.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":134.038,"end":136.826},{"lang":"en-US","text":"The purchase order requires internal approval.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":137.326,"end":140.187},{"lang":"en-US","text":"stakeholder.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":141.887,"end":143.017},{"lang":"en-US","text":"A person or group affected by an activity or its result.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":143.317,"end":147.084},{"lang":"en-US","text":"Each stakeholder needs the confirmed delivery information.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":147.584,"end":151.211},{"lang":"en-US","text":"procurement.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":152.911,"end":154.127},{"lang":"en-US","text":"The purchasing process or the team responsible for it.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":154.427,"end":157.843},{"lang":"en-US","text":"Procurement will review the quotation.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":158.343,"end":160.649},{"lang":"en-US","text":"win-win.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":162.349,"end":163.437},{"lang":"en-US","text":"An option intended to benefit both sides.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":163.737,"end":166.522},{"lang":"en-US","text":"A smaller sample order could be a win-win solution.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":167.022,"end":170.171},{"lang":"en-US","text":"close a deal.","pauseMs":300,"rate":86,"role":"narrator","pitch":0,"voice":"af_heart","start":171.871,"end":173.087},{"lang":"en-US","text":"Reach a commercial agreement, subject to the required approvals.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":173.387,"end":177.248},{"lang":"en-US","text":"We cannot close a deal before approval.","pauseMs":1700,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":177.748,"end":179.993}],"start":49.014,"end":181.693},{"id":"pronunciation","title":"Pronunciation and repetition","segments":[{"lang":"en-US","text":"Now focus on pronunciation. The examples are spoken models, not a pronunciation score. Listen for the stronger beat and how words join in a phrase. Repeat slowly, then say the whole phrase naturally.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":181.693,"end":195.283},{"lang":"en-US","text":"Freight rhymes with late and wait. The letters G and H are not pronounced here. Listen to freight, late, wait, then repeat freight.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":195.783,"end":203.984},{"lang":"en-US","text":"freight.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":204.484,"end":205.572},{"lang":"en-US","text":"freight.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":207.372,"end":208.193},{"lang":"en-US","text":"Quotation has its strongest beat in the middle. Invoice has a strong first beat. Listen to the contrast and keep the document meanings separate.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":209.993,"end":219.017},{"lang":"en-US","text":"quotation and invoice.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":219.517,"end":221.462},{"lang":"en-US","text":"quotation and invoice.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":223.262,"end":224.821},{"lang":"en-US","text":"The strongest beat is in the middle of procurement. Start gently and make the middle easy to hear. Then use the word inside a complete sentence.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":226.621,"end":235.569},{"lang":"en-US","text":"procurement.","pauseMs":1800,"rate":78,"role":"narrator","pitch":0,"voice":"af_heart","start":236.069,"end":237.456},{"lang":"en-US","text":"procurement.","pauseMs":1800,"rate":98,"role":"narrator","pitch":0,"voice":"af_heart","start":239.256,"end":240.322},{"lang":"en-US","text":"Freight. Late. Wait. Procurement will review the quotation.","pauseMs":1800,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":242.123,"end":245.966}],"start":181.693,"end":247.766},{"id":"dialogue","title":"Workplace dialogue","segments":[{"lang":"en-US","text":"Listen to the complete conversation. Notice the request, the clarification and the final commitment. The two roles keep the same delivery throughout. Read the transcript afterwards if you need support.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":247.766,"end":260.492},{"lang":"en-US","text":"Our supply chain review shows a delay in one component. Can we discuss the sample order?","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"voice":"af_heart","start":260.992,"end":266.923},{"lang":"en-US","text":"Yes. Is the supplier able to provide twenty sample units?","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"voice":"am_michael","start":267.323,"end":271.643},{"lang":"en-US","text":"The quotation covers twenty units, but it does not include freight.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"voice":"af_heart","start":272.043,"end":276.054},{"lang":"en-US","text":"Please list freight separately so procurement can compare the total cost.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"voice":"am_michael","start":276.454,"end":281.169},{"lang":"en-US","text":"The estimated lead time is ten working days after order confirmation. It is not yet a guaranteed date.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"voice":"af_heart","start":281.569,"end":288.748},{"lang":"en-US","text":"Understood. We cannot send the purchase order before internal approval.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"voice":"am_michael","start":289.148,"end":294.097},{"lang":"en-US","text":"Once the order is confirmed, the shipment will contain only the sample units.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"voice":"af_heart","start":294.497,"end":299.424},{"lang":"en-US","text":"Please make sure the invoice shows the agreed unit price and the separate freight charge.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"voice":"am_michael","start":299.824,"end":305.456},{"lang":"en-US","text":"I will send the revised quotation tomorrow. Which stakeholder should receive the delivery update?","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"voice":"af_heart","start":305.856,"end":311.372},{"lang":"en-US","text":"Our procurement contact should receive it. A small sample order could be a win-win solution before a larger commitment.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"voice":"am_michael","start":311.772,"end":320.469},{"lang":"en-US","text":"That makes sense. We can close a deal only after the price and approval are confirmed.","pauseMs":400,"rate":94,"role":"Elliot","pitch":-1,"voice":"af_heart","start":320.869,"end":325.863},{"lang":"en-US","text":"Agreed. Send the price, freight and delivery estimate in writing tomorrow, and procurement will review them.","pauseMs":400,"rate":90,"role":"Noor","pitch":2,"voice":"am_michael","start":326.263,"end":333.82},{"lang":"en-US","text":"Listen again later and take one role. Pause before that person speaks and predict the response. A different answer can still be appropriate if it communicates the same goal clearly.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":334.22,"end":345.506}],"start":247.766,"end":346.006},{"id":"practice","title":"Your turn to respond","segments":[{"lang":"en-US","text":"Your turn. You will hear four prompts. After each prompt there is a short pause for your response, followed by one possible model. Pause the player if you need more time. The model is not the only correct answer.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":346.006,"end":359.418},{"lang":"en-US","text":"Does your quotation include every cost?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":359.918,"end":362.405},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":366.905,"end":368.548},{"lang":"en-US","text":"Could you confirm whether freight is included and list it separately?","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":368.748,"end":372.685},{"lang":"en-US","text":"Can you guarantee delivery in ten days?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":374.285,"end":376.739},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":381.239,"end":382.882},{"lang":"en-US","text":"The current estimate is ten working days after order confirmation; I cannot guarantee a date yet.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":383.082,"end":389.494},{"lang":"en-US","text":"Can we send the purchase order now?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":391.094,"end":393.06},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":397.56,"end":399.202},{"lang":"en-US","text":"Not yet. Procurement must review the revised quotation and approve the order first.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":399.402,"end":405.001},{"lang":"en-US","text":"What should we confirm tomorrow?","pauseMs":4500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":406.601,"end":408.408},{"lang":"en-US","text":"One possible response is:","pauseMs":200,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":412.908,"end":414.55},{"lang":"en-US","text":"Please confirm the price, freight and delivery estimate in writing tomorrow.","pauseMs":1600,"rate":92,"role":"narrator","pitch":0,"voice":"af_heart","start":414.75,"end":419.456}],"start":346.006,"end":421.056},{"id":"summary","title":"Recap and application","segments":[{"lang":"en-US","text":"To recap, choose three expressions from the episode and use them in a short message. Check the goal, the person responsible and the next step. Keep observed facts separate from predictions. Return to the lesson for the games, grammar practice and final review.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":421.056,"end":437.503},{"lang":"en-US","text":"This is a practice activity. Listening and self-assessment do not certify pronunciation or proficiency. Ask your teacher for feedback and repeat one chapter with a specific improvement in mind. Thank you for studying with I S M Business.","pauseMs":500,"rate":94,"role":"narrator","pitch":0,"voice":"af_heart","start":438.003,"end":453.916}],"start":421.056,"end":454.416}],"audio":"assets/podcasts/supplier-delivery-agreement-en.mp3","duration":454.416,"bytes":5453900,"sha256":"9b1bd7b2f623c943deabd2d2a50ebf84628f42e4c243052833b2f66cab982341"}},"disclosure":"Vozes neurais sintetizadas com Kokoro: Dora (português), Heart e Michael (inglês). Cada personagem mantém uma voz própria. Não são gravações de atores."}];
